template < class T1,class T2>
ostream &operator <<(ostream &os,const pair < T1,T2 > &p)
{
    os<<"{"<<p.first<<","<<p.second<<"}";
    return os;
}

typedef int fType;

struct edge
{
    int from, to;
    fType cap, flow;
    edge(int from, int to, fType cap, fType flow = 0) : from(from), to(to), cap(cap), flow(flow) {}
};

struct PushRelabel
{
    int N;
    vector<edge> edges;
    vector<vector<int> > G;
    vector<int> h, inQ, count;
    vector<fType> excess;
    queue<int> Q;
    PushRelabel(int N) : N(N), count(N<<1), G(N), h(N), inQ(N), excess(N) {}

    int addEdge(int from, int to, int cap)
    {
        G[from].push_back(edges.size());
        edges.push_back(edge(from, to, cap));
        G[to].push_back(edges.size());
        edges.push_back(edge(to, from, 0));
        return G[from].back();
    }

    void enQueue(int u)
    {
        if(!inQ[u] && excess[u] > 0) Q.push(u), inQ[u] = true;
    }

    void Push(int edgeIdx)
    {
        edge & e = edges[edgeIdx];
        int toPush = min<fType>(e.cap - e.flow, excess[e.from]);
        if(toPush > 0 && h[e.from] > h[e.to])
        {
            e.flow += toPush;
            excess[e.to] += toPush;
            excess[e.from] -= toPush;
            edges[edgeIdx^1].flow -= toPush;
            enQueue(e.to);
        }
    }

    void Relabel(int u)
    {
        count[h[u]] -= 1;
        h[u] = 2*N-2;
        for (int i = 0; i < G[u].size(); ++i)
        {
            edge & e = edges[G[u][i]];
            if(e.cap > e.flow) h[u] = min(h[u], h[e.to]);
        }
        count[++h[u]] += 1;
    }

    void gapRelabel(int height)
    {
        for (int u = 0; u < N; ++u) if(h[u] >= height && h[u] < N)
            {
                count[h[u]] -= 1;
                count[h[u] = N] += 1;
                enQueue(u);
            }
    }

    void Discharge(int u)
    {
        for (int i = 0; excess[u] > 0 && i < G[u].size(); ++i)
        {
            Push(G[u][i]);
        }
        if(excess[u] > 0)
        {
            if(h[u] < N && count[h[u]] < 2) gapRelabel(h[u]);
            else Relabel(u);
        }
        else if(!Q.empty())   // dequeue
        {
            Q.pop();
            inQ[u] = false;
        }
    }

    fType getFlow(int src, int snk)
    {
        h[src] = N;
        inQ[src] = inQ[snk] = true;
        count[0] = N - (count[N] = 1);
        for (int i = 0; i < G[src].size(); ++i)
        {
            excess[src] += edges[G[src][i]].cap;
            Push(G[src][i]);
        }
        while (!Q.empty())
        {
            Discharge(Q.front());
        }
        return excess[snk];
    }
};

const int N=20+5;
const int oo=1e4+7;
int dis[N][N];
string s[N];
string t[N];
int n,k;
int dx[]= {1,0,-1,0};
int dy[]= {0,1,0,-1};

vector<pii> source,sink;

int sinkid[N][N];

void bfs(int x,int y)
{
    memset(dis, -1, sizeof dis);
    queue<pii> q;
    dis[x][y]= 0;
    q.push({x,y});

    while(!q.empty())
    {
        x=  q.front().first;
        y=  q.front().second;
        q.pop();

        for(int j=0; j<4; j++)
        {
            int xx =x+dx[j];
            int yy =y+dy[j];

            if(xx<0 || xx>= n || yy<0 || yy>= n) continue;
            if(dis[xx][yy] !=-1) continue;
            if(t[xx][yy]=='Y' || t[xx][yy]=='Z') continue;
            dis[xx][yy]= dis[x][y]+1;
            q.push({xx,yy});
        }
    }
}

int dp[65][12][12][12][12];

int pos(int t,int x0,int y0, int x,int y)
{
    if(dis[x0][y0]< t) return 0;
    if(x0==x && y0==y) return 1;
    if(t>=k) return 0;
    if(dis[x0][y0]<=t) return 0;

    if(dp[t][x0][y0][x][y]!=-1) return dp[t][x0][y0][x][y];

    for(int j=0; j<4; j++)
    {
        int xx = x0+dx[j];
        int yy = y0+dy[j];

        if(xx<0 || xx>= n || yy<0 || yy>= n) continue;
        if(s[xx][yy]=='Y' || s[xx][yy]=='Z') continue;

        if(pos(t+1 , xx ,yy , x , y)) return dp[t][x0][y0][x][y]=1;
    }
    return dp[t][x0][y0][x][y]=0;
}

int32_t main()
{
    FastIO;
    memset(dp , -1 , sizeof dp);
    cin>>n>>k;
    for(int i=0; i<n; i++) cin>>s[i];
    for(int i=0; i<n; i++) cin>>t[i];

    int x= -1, y = -1 ;
    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++) if(t[i][j]== 'Z') x= i, y = j;
    }
    bfs(x,y);
    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++) dis[i][j] = dis[i][j]==-1 ? oo : dis[i][j];
    }

    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++){
            char c = s[i][j];
            if(c=='Z' || c=='Y' || c=='0') continue;
            source.push_back({i,j});
        }
    }
    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++){
            char c = t[i][j];
            if(c=='Z' || c=='Y' || c=='0') continue;
            sink.push_back({i,j});
        }
    }

    PushRelabel g(source.size()  + sink.size()  + 2);
    for(int i=0;i<source.size();i++) g.addEdge(0,i+1 , s[source[i].first][source[i].second]-'0');
    for(int i=0;i<sink.size();i++) g.addEdge(source.size() + i+1  ,source.size()  + sink.size()  + 1,  t[sink[i].first][sink[i].second]-'0');
    for(int i=0;i<source.size();i++){
        for(int j=0;j<sink.size();j++){
            if(pos(0,source[i].first  , source[i].second , sink[j].first , sink[j].second))
                g.addEdge(i+1 , source.size()+j+1 , oo);
        }
    }
    cout<<g.getFlow(0,source.size() + sink.size() + 1);
}
